// ET-014 PR-2: the ET-005b synthetic simulator scenarios replayed through the trip reducer and a first-insert storage
// model (tests/shared/trip-replay.ts), compared with hand-written tests/fixtures/simulator-v1/<id>.trip.expected.json.
// Each expectation is written from the scenario definition, its hand-written wire expectation, docs/trips.md and the
// T1–T20 decisions; none is generated by this code. Seeded identifiers and trip UUIDs appear as labels: a trip is
// `trip@<eventSeq of its job configuration>`, derived here with an independent node:crypto implementation of T4, and a
// late-attach trip (ET-016 PR-7, J9) is `attach@<the checkpoint's nextEventSeq>` over its own prefix.
import {createHash} from 'node:crypto';
import {existsSync, readFileSync} from 'node:fs';
import {describe, expect, it} from 'vitest';
import {tripView, type TripSummaryView} from '../../packages/telemetry-core/src/index';
import {readFixtureFile} from '../../tools/telemetry-simulator/src/fixture-file';
import {replayV1, type ConnectionRecord, type TranscriptLine} from '../../tools/telemetry-simulator/src/v1/replay';
import {validateServerMessage, type ServerMessage} from '../../packages/contracts/src/protocol-v1';
import {BASE_UTC, ETS2_A, GAME_CLOCK_1, Script, r} from '../shared/trip-messages';
import {seededId} from '../../tools/telemetry-simulator/src/v1/source';
import {SIMULATOR_V1_DIR, scenarioPath} from '../shared/simulator-v1-expected';
import {replayTrips, type TripReplay} from '../shared/trip-replay';

const SCENARIOS = ['normal-delivery', 'app-absent-hydration', 'save-load', 'timers-truck-refuel', 'ferry-train', 'sleep-teleport', 'quick-job-profile-change',
  'clock-change-suspend', 'reconnect-lost-ack', 'crash-before-commit', 'crash-after-commit', 'retention-expired'];
const tripExpectedPath = (id: string) => `${SIMULATOR_V1_DIR}/${id}.trip.expected.json`;
interface TripExpected {scenario: string; basis: string[]; authoredFrom: string[]; trips: unknown[]; attributions: unknown[]; intervals: unknown[]; coverage: unknown; view: unknown}

function labels(seed: string): Map<string, string> {
  const map = new Map<string, string>(), session = seededId(seed, 'plugin-session');
  for (const label of ['plugin-session', 'process-instance', 'capture-clock']) map.set(seededId(seed, label), label);
  for (let n = 0; n < 20; n++) map.set(seededId(seed, `game-clock-${n}`), `game-clock-${n}`);
  for (let seq = 1; seq <= 200; seq++) {
    const h = createHash('sha256').update(`ets2telemetry-trip-v1:${session}:${seq}`, 'utf8').digest('hex');
    map.set(`${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20, 32)}`, `trip@${seq}`);
    const a = createHash('sha256').update(`ets2telemetry-trip-attach-v1:${session}:${seq}`, 'utf8').digest('hex');
    map.set(`${a.slice(0, 8)}-${a.slice(8, 12)}-${a.slice(12, 16)}-${a.slice(16, 20)}-${a.slice(20, 32)}`, `attach@${seq}`);
  }
  return map;
}
function trip(view: TripSummaryView | null) {
  if (view === null) return null;
  return {trip: view.tripUuid, recordingCompleteness: view.recordingCompleteness, observedDistanceM: view.observedDistanceM, fuelUsedL: view.fuelUsedL,
    refuelledL: view.refuelledL, refuels: view.refuels};
}
/** The stored rows and the final view of the scenario's game, with seeded identifiers replaced by labels. */
function summarize(replay: TripReplay, map: Map<string, string>, pluginSessionId: string, game: 'ets2' | 'ats') {
  const s = replay.storage, view = tripView(replay.state, game);
  const out = {
    trips: s.trips.map(t => ({trip: t.tripUuid, jobConfigurationEventSeq: t.jobConfigurationEventSeq, truckConfigurationEventSeq: t.truckConfigurationEventSeq,
      trailerConfigurationEventSeqs: t.trailerConfigurationEventSeqs, openedEventSeq: t.openedEventSeq, gameMode: t.gameMode, gameModeAmbiguous: t.gameModeAmbiguous,
      outcome: t.outcome, outcomeEventSeq: t.outcomeEventSeq, closeReason: t.closeReason, recordingCompleteness: t.recordingCompleteness, startedUtcMs: t.startedUtcMs,
      endedUtcMs: t.endedUtcMs, observedDistanceM: t.observedDistanceM, fuelUsedL: t.fuelUsedL})),
    attributions: s.attributions.map(a => ({eventSeq: a.eventSeq, trip: a.tripUuid, attribution: a.attribution})),
    intervals: s.intervals.map(i => {
      const {tripUuid, ...rest} = i, row: Record<string, unknown> = {trip: tripUuid ?? null, ...rest};
      delete row.pluginSessionId;
      return row;
    }),
    coverage: {committedThroughEventSeq: s.committedThrough(pluginSessionId), ...s.statuses},
    view: {phase: view.phase, untrackedJob: view.untrackedJob, current: trip(view.current),
      lastClosed: view.lastClosed === null ? null : {...trip(view.lastClosed), outcome: view.lastClosed.outcome, closeReason: view.lastClosed.closeReason}}
  };
  return JSON.parse(JSON.stringify(out), (_key, v: unknown) => typeof v === 'string' && map.has(v) ? map.get(v) : v) as unknown;
}

describe('trip replay of the simulator v1 corpus (T16, T17; REG-001 to REG-008)', () => {
  it('has a hand-written trip expectation for each listed scenario, tagged with its evidence basis', () => {
    for (const id of SCENARIOS) {
      expect(existsSync(tripExpectedPath(id)), id).toBe(true);
      const expected = JSON.parse(readFileSync(tripExpectedPath(id), 'utf8')) as TripExpected;
      expect(expected.scenario).toBe(id);
      expect(expected.basis.length, id).toBeGreaterThan(0);
      expect(expected.authoredFrom.length, id).toBeGreaterThan(0);
    }
  });
  for (const id of SCENARIOS) it(`scenario ${id} meets its hand-written trip expectation`, () => {
    const scenario = readFixtureFile(scenarioPath(id)) as {seed: string; game: 'ets2' | 'ats'};
    const result = replayV1(scenario), replay = replayTrips(result);
    // The storage model commits exactly what the scripted client committed.
    expect(replay.storage.committedThrough(seededId(scenario.seed, 'plugin-session'))).toBe(result.ledger.committedThroughEventSeq);
    // The reducer state is plain data.
    expect(JSON.parse(JSON.stringify(replay.state))).toEqual(replay.state);
    const expected = JSON.parse(readFileSync(tripExpectedPath(id), 'utf8')) as TripExpected;
    expect(summarize(replay, labels(scenario.seed), seededId(scenario.seed, 'plugin-session'), scenario.game)).toEqual({trips: expected.trips, attributions: expected.attributions, intervals: expected.intervals,
      coverage: expected.coverage, view: expected.view});
  });
});

// Fix round 1: no listed scenario has an active trip with changing readings, so this test-only transcript, built from the
// shared fixtures and the trip-messages Script, drives the wire -> normalizeV1State -> accounting path with real changes.
// It is not a simulator scenario and changes no fixture. Readings carry source time 1,000,000,000,000 ns + ms × 1,000,000
// and UTC BASE_UTC + ms; the script's events sit at their clock minus 1 ms.
describe('trip replay of a synthetic transcript with readings accounting (fix round 1)', () => {
  const ns = (ms: number) => (1_000_000_000_000n + BigInt(ms) * 1_000_000n).toString();
  function snapshot(s: Script, ms: number, odometer: number, fuel: number, minutes: number): ServerMessage {
    const message = JSON.parse(readFileSync('tests/fixtures/protocol-v1/snapshot.json', 'utf8')) as Extract<ServerMessage, {kind: 'snapshot'}>;
    message.source = {game: 'ets2', pluginSessionId: s.session, processInstanceId: `20000000${s.session.slice(8)}`, processId: 4242, windowsSessionId: 1, origin: 'synthetic'};
    message.seq = String(100 + ms); message.capture = {clockId: s.clockId, monotonicNs: ns(ms)};
    Object.assign(message.data.state, {simulation: 'running', odometer: {available: true, value: odometer, unit: 'm'}, fuel: {available: true, value: fuel, unit: 'L'},
      gameTime: {available: true, value: String(minutes), unit: 'min', clockId: GAME_CLOCK_1}, captureUtcUnixMs: {available: true, value: String(BASE_UTC + ms)}});
    return validateServerMessage(message);
  }
  it('stores the observed distance, a reading hole, a refuel and a game-time jump of an active trip [synthetic-inference]', () => {
    const s = new Script(ETS2_A), paused = {simulation: 'paused'} as const;
    const messages: ServerMessage[] = [s.welcome(), s.checkpoint(null), s.event(r.started()), s.event(r.jobConfigured()),
      snapshot(s, 2000, 100_000, 400, 600), snapshot(s, 3000, 100_020, 399.5, 600), snapshot(s, 10_000, 100_150, 399, 601), snapshot(s, 11_000, 100_150, 450, 601),
      snapshot(s, 12_000, 100_150, 450, 700), s.event(r.paused(), {...paused, advanceMs: 11_000}), s.event(r.delivered(), paused)];
    const connection: ConnectionRecord = {connection: 1, openedAtMs: 0, durableRequested: true, clientInstanceId: 'synthetic-client', clientClockId: 'synthetic-clock',
      closedBy: 'disconnect', mappings: [], policy: {durable: true, commit: {kind: 'each'}, ack: {kind: 'each'}}, actions: [], refusedClients: 0};
    const transcript: TranscriptLine[] = messages.map(message => ({scenario: 'synthetic-accounting', origin: 'synthetic', connection: 1, atMs: 0, direction: 'server', message}));
    const replay = replayTrips({transcript, connections: [connection]});
    const createHashed = createHash('sha256').update(`ets2telemetry-trip-v1:${ETS2_A}:2`, 'utf8').digest('hex');
    const trip = `${createHashed.slice(0, 8)}-${createHashed.slice(8, 12)}-${createHashed.slice(12, 16)}-${createHashed.slice(16, 20)}-${createHashed.slice(20, 32)}`;
    const view = (lastClosed: Record<string, unknown>) => ({phase: 'idle', untrackedJob: false, current: null, lastClosed});
    expect(summarize(replay, new Map([[trip, 'trip@2'], [s.clockId, 'capture-clock']]), ETS2_A, 'ets2')).toEqual({
      // The job opens while running (eventSeq 2) and the delivery (eventSeq 4) closes it partial because of the hole.
      trips: [{trip: 'trip@2', jobConfigurationEventSeq: '2', truckConfigurationEventSeq: null, trailerConfigurationEventSeqs: [], openedEventSeq: '2',
        gameMode: {mode: 'unknown', method: 'none', confidence: 'none'}, gameModeAmbiguous: false, outcome: 'delivered', outcomeEventSeq: '4', closeReason: 'outcome',
        recordingCompleteness: 'partial', startedUtcMs: BASE_UTC + 2000, endedUtcMs: BASE_UTC + 14_000, observedDistanceM: {available: true, value: 150},
        // ET-016 PR-6 (J8): fuel used is stored as well, 0.5 + 0.5 L (see the view below); the 450 -> 450 L step adds 0 L.
        fuelUsedL: {available: true, value: 1}}],
      attributions: [{eventSeq: '4', trip: 'trip@2', attribution: 'trip'}],
      intervals: [
        // 7 s of running time between the snapshots at 3,000 and 10,000 ms; 130 m across it is continuous.
        {trip: 'trip@2', kind: 'sample-loss', startUtcMs: BASE_UTC + 3000, endUtcMs: BASE_UTC + 10_000, startMonotonicNs: ns(3000), endMonotonicNs: ns(10_000),
          sourceClockId: 'capture-clock', detail: {cause: 'reading-hole'}},
        {trip: 'trip@2', kind: 'discontinuity', detail: {annotation: true, cause: 'refuel', addedLiters: 51, atMonotonicNs: ns(11_000)}},
        // 99 game minutes in 1 s from the previous snapshot, with no transfer: a possible sleep.
        {trip: 'trip@2', kind: 'discontinuity', detail: {annotation: true, cause: 'game-time-jump', label: 'possible-sleep', fromMinutes: '601', toMinutes: '700', atMonotonicNs: ns(12_000)}}
      ],
      coverage: {committedThroughEventSeq: '4', committed: 4, duplicate: 0, covered: 0},
      // 20 + 130 m; fuel used 0.5 + 0.5 L, the 51 L refuel apart.
      view: view({trip: 'trip@2', recordingCompleteness: 'partial', observedDistanceM: {state: 'value', value: 150}, fuelUsedL: {state: 'value', value: 1},
        refuelledL: 51, refuels: 1, outcome: 'delivered', closeReason: 'outcome'})
    });
    expect(replay.readings).toBe(6);
  });
});
